CREATE TABLE jobs (job_id VARCHAR(36) PRIMARY KEY, content_id VARCHAR(36) NOT NULL, version INT NOT NULL, status VARCHAR(30) NOT NULL, created_by VARCHAR(36) NOT NULL, correlation_id VARCHAR(100), created_at VARCHAR(35) NOT NULL, updated_at VARCHAR(35) NOT NULL);
CREATE TABLE job_targets (target_id VARCHAR(36) PRIMARY KEY, job_id VARCHAR(36) NOT NULL, lang VARCHAR(20) NOT NULL, voice_id VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, error_code VARCHAR(40), translation_id VARCHAR(36), audio_id VARCHAR(36), updated_at VARCHAR(35) NOT NULL, CONSTRAINT fk_target_job FOREIGN KEY (job_id) REFERENCES jobs(job_id), CONSTRAINT uq_job_lang UNIQUE (job_id, lang));
CREATE TABLE idempotency_records (record_id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, operation VARCHAR(80) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, request_hash VARCHAR(64) NOT NULL, job_id VARCHAR(36) NOT NULL, created_at VARCHAR(35) NOT NULL, expires_at VARCHAR(35) NOT NULL, CONSTRAINT uq_idempotency UNIQUE (user_id, operation, idempotency_key));
CREATE TABLE outbox_events (event_id VARCHAR(36) PRIMARY KEY, exchange_name VARCHAR(80) NOT NULL, routing_key VARCHAR(80) NOT NULL, payload VARCHAR(4000) NOT NULL, correlation_id VARCHAR(100), occurred_at VARCHAR(35) NOT NULL, published BIT NOT NULL DEFAULT 0);
CREATE TABLE job_creation_locks (lock_key VARCHAR(120) PRIMARY KEY);
CREATE TABLE event_attempts (event_id VARCHAR(36) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, updated_at VARCHAR(35) NOT NULL);
